@verbatim<script>(function(){var M=document.getElementById('cmModal'),cur=null,cat='';
function E(t,c){var d=document.createElement('div');d.style.cssText='border-top:1px solid #E5E7EB;padding:7px 0';var a=document.createElement('div');a.style.cssText='font-size:12px;color:#6B7280';a.textContent=c;var b=document.createElement('div');b.style.whiteSpace='pre-wrap';b.textContent=t;d.appendChild(a);d.appendChild(b);return d}
function paint(j){var h=document.getElementById('cmHist');h.innerHTML='';if(!j.rows.length){h.textContent='No comments yet.';return}j.rows.forEach(function(r){h.appendChild(E(r.body,r.t+' · '+r.by+(r.cat?' · '+r.cat:'')+(r.inv?' · from '+r.inv:'')))});}
function setCell(id,j){var c=document.getElementById('cm'+id);if(c)c.textContent=j.last?(j.last.length>50?j.last.slice(0,49)+'…':j.last):'—'}
function open(id,inv){cur=id;cat='';document.getElementById('cmInv').textContent=inv;document.getElementById('cmBody2').value='';document.getElementById('cmTpl2').value='';document.getElementById('cmMsg').textContent='';document.getElementById('cmHist').textContent='Loading…';M.style.display='flex';fetch('/admin/orders/'+id+'/comments',{headers:{Accept:'application/json'}}).then(function(r){return r.json()}).then(paint)}
document.querySelectorAll('.cmEdit').forEach(function(a){a.addEventListener('click',function(e){e.preventDefault();open(a.dataset.id,a.dataset.inv)})});
document.getElementById('cmX').addEventListener('click',function(e){e.preventDefault();M.style.display='none'});
M.addEventListener('click',function(e){if(e.target===M)M.style.display='none'});
document.getElementById('cmTpl2').addEventListener('change',function(){var o=this.options[this.selectedIndex];if(!this.value)return;document.getElementById('cmBody2').value=this.value;cat=o.getAttribute('data-g')||''});
document.getElementById('cmSave').addEventListener('click',function(){var b=document.getElementById('cmBody2').value.trim();if(!b){document.getElementById('cmMsg').textContent='Write a comment first.';return}var fd=new FormData();fd.append('_token',M.dataset.t);fd.append('body',b);fd.append('category',cat);document.getElementById('cmMsg').textContent='Saving…';fetch('/admin/orders/'+cur+'/comment',{method:'POST',body:fd,headers:{Accept:'application/json'}}).then(function(r){return r.json()}).then(function(j){document.getElementById('cmMsg').textContent='Saved ✓';document.getElementById('cmBody2').value='';document.getElementById('cmTpl2').value='';cat='';paint(j);setCell(cur,j)}).catch(function(){document.getElementById('cmMsg').textContent='Could not save, try again.'})});
})();</script>@endverbatim
